declare(strict_types=1);require_once __DIR__.'/error_bootstrap.php';ini_set('session.cookie_httponly','1');ini_set('session.cookie_samesite','Strict');if(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')ini_set('session.cookie_secure','1');session_start();date_default_timezone_set('Asia/Tehran');header('Cache-Control:no-store,private');
if(!file_exists(__DIR__.'/config.php')){header('Location:install.php');exit;}$c=require __DIR__.'/config.php';
try{$pdo=new PDO('mysql:host='.$c['db_host'].';dbname='.$c['db_name'].';charset=utf8mb4',$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);require_once __DIR__.'/schema.php';ensure_product_schema($pdo);require_once __DIR__.'/admin_auth.php';ts_admin_schema($pdo);require_once __DIR__.'/coupon_lib.php';ts_coupon_schema($pdo);}catch(Throwable $e){ts_log_internal($e,'SYS-101');ts_html_fail('SYS-101',503,'index.php');}
$me=ts_require_roles($pdo,['owner','manager']);function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function token(){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];}$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){ts_html_fail('REQ-102',419,'index.php');}$a=(string)($_POST['action']??'');try{
 if($a==='create'){$code=mb_strtoupper(trim((string)($_POST['code']??'')));$type=(string)($_POST['type']??'percent');$value=max(0,(int)($_POST['value']??0));$min=max(0,(int)($_POST['min_order']??0));$max=max(0,(int)($_POST['max_discount']??0));$limit=max(0,(int)($_POST['usage_limit']??0));if(!preg_match('/^[A-Z0-9_-]{3,40}$/',$code))throw new RuntimeException('کد باید حداقل ۳ کاراکتر و شامل حروف انگلیسی/عدد باشد.');if(!in_array($type,['percent','fixed','free_shipping'],true))throw new RuntimeException('نوع کد نامعتبر است.');if($type==='percent'&&($value<1||$value>100))throw new RuntimeException('درصد باید بین ۱ تا ۱۰۰ باشد.');if($type==='fixed'&&$value<1)throw new RuntimeException('مبلغ تخفیف را وارد کنید.');$st=$pdo->prepare('INSERT INTO coupons(code,type,value,min_order,max_discount,usage_limit,active,created_at) VALUES(?,?,?,?,?,?,1,NOW())');$st->execute([$code,$type,$value,$min,$max,$limit]);$msg='کد تخفیف ساخته شد.';}
 if($a==='toggle'){$id=max(0,(int)($_POST['id']??0));$pdo->prepare('UPDATE coupons SET active=1-active,updated_at=NOW() WHERE id=?')->execute([$id]);$msg='وضعیت کد تغییر کرد.';}
 if($a==='delete'){$id=max(0,(int)($_POST['id']??0));$pdo->prepare('DELETE FROM coupons WHERE id=?')->execute([$id]);$msg='کد حذف شد.';}
 }catch(Throwable $x){$err=ts_error_text('SYS-100');ts_log_internal($x,'SYS-100');}}
