?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>کدهای تخفیف</title><link rel="stylesheet" href="assets/style.css"><style>.wrap{max-width:950px;margin:20px auto;padding:0 12px}.coupon{background:#fff;border:1px solid #e4ece6;border-radius:15px;padding:13px;margin:9px 0;display:grid;grid-template-columns:1fr auto;gap:10px}.code{font-family:monospace;direction:ltr;font-size:18px;font-weight:800}.off{color:#888}@media(max-width:650px){.coupon{grid-template-columns:1fr}}</style></head><body><header class="top"><a class="brand" href="admin.php"><span class="logo">🎁</span><span><b>کدهای تخفیف</b><small>درصدی، مبلغ ثابت و ارسال رایگان</small></span></a><a class="btn pale" href="admin.php">مدیریت اصلی</a></header><main class="wrap"><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="notice"><?=e($err)?></div><?php endif;?><section class="panel"><h2>+ کد جدید</h2><form method="post" class="checkout"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="create"><label>کد<input name="code" required placeholder="WELCOME"></label><label>نوع<select name="type"><option value="percent">درصدی</option><option value="fixed">مبلغ ثابت</option><option value="free_shipping">ارسال رایگان</option></select></label><label>مقدار<input type="number" name="value" min="0" value="10"></label><label>حداقل خرید<input type="number" name="min_order" min="0" value="0"></label><label>سقف تخفیف (۰=بدون سقف)<input type="number" name="max_discount" min="0" value="0"></label><label>تعداد استفاده (۰=نامحدود)<input type="number" name="usage_limit" min="0" value="0"></label><button class="btn wide">ساخت کد</button></form></section><section class="panel"><h2>کدهای موجود</h2><?php foreach($rows as $r):?><div class="coupon <?=$r['active']?'':'off'?>"><div><span class="code"><?=e($r['code'])?></span> · <?=e(['percent'=>'درصدی','fixed'=>'مبلغ ثابت','free_shipping'=>'ارسال رایگان'][$r['type']]??$r['type'])?><div class="muted">مقدار <?=number_format((int)$r['value'])?> · حداقل خرید <?=number_format((int)$r['min_order'])?> · استفاده <?=number_format((int)$r['used_count'])?><?=((int)$r['usage_limit']>0)?' از '.number_format((int)$r['usage_limit']):''?></div></div><div style="display:flex;gap:6px"><form method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn pale"><?=$r['active']?'غیرفعال':'فعال'?></button></form><form method="post" onsubmit="return confirm('کد حذف شود؟')"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn danger">حذف</button></form></div></div><?php endforeach;?></section></main></body></html>
